					if _res.Error != nil {
						t.Errorf("exec error: %v\n  sql: %s", _res.Error, "\n      PRAGMA locking_mode = EXCLUSIVE;\n      PRAGMA journal_mode = WAL;\n      PRAGMA locking_mode = NORMAL;\n      PRAGMA user_version;\n      PRAGMA journal_mode = DELETE;\n    ")
					}
